import{_ as a,o as n,c as e,ai as l}from"./chunks/framework.ampVZV4B.js";const h=JSON.parse('{"title":"Context & Rules","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/coding/context-and-rules.md","filePath":"ai/dev/coding/context-and-rules.md"}'),i={name:"ai/dev/coding/context-and-rules.md"};function p(r,s,t,c,o,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="context-rules" tabindex="-1">Context &amp; Rules <a class="header-anchor" href="#context-rules" aria-label="Permalink to “Context &amp; Rules”">​</a></h1><blockquote><p>一页讲清楚：给 AI 什么信息（Context），约束它怎么改（Rules）。够用即可，不建复杂规范体系。</p></blockquote><h3 id="什么时候用" tabindex="-1">什么时候用？ <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用？”">​</a></h3><ul><li>AI 不理解项目</li><li>AI 总改错位置</li><li>AI 不遵守项目规范</li><li>每次都要重复解释项目背景</li></ul><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><p>建立可复用的 <strong>Context + Rules</strong>。</p><blockquote><p>不是给 AI 塞更多信息，而是给足够且必要的上下文。</p></blockquote><p>核心：</p><blockquote><p><strong>Context = 这个项目现在是什么。Rules = 在这个项目里应该怎么做。</strong></p></blockquote><p>没有 Context，AI 只能猜。<br> 没有 Rules，AI 容易用「它喜欢的写法」生成你维护不了的代码。</p><p>仓库里的正式文件只维护一份：<a href="/my-vitepress-site/ai/dev/coding/project-landing-kit.html">项目落地包</a>。<br> 本页模板只用于<strong>单次任务</strong>贴进对话，不要再另写一套 AGENTS。</p><p>执行顺序：</p><ul><li>新仓：<a href="/my-vitepress-site/ai/ai-programming/cursor-new-project.html">新项目实战</a></li><li>老仓：<a href="/my-vitepress-site/ai/ai-programming/cursor-legacy-project.html">老项目实战</a></li><li>Skill 何时启用：<a href="/my-vitepress-site/ai/dev/coding/skills-in-coding.html">Skills</a></li></ul><hr><h2 id="context-包含什么" tabindex="-1">Context 包含什么 <a class="header-anchor" href="#context-包含什么" aria-label="Permalink to “Context 包含什么”">​</a></h2><p>让 AI 理解「当前项目与当前任务」：</p><ul><li>项目概览（做什么、给谁用）</li><li>技术栈（语言、框架、关键中间件）</li><li>模块关系（谁调谁）</li><li>数据模型（核心表 / 实体）</li><li>API / 调用链（与本次任务相关的）</li><li>当前任务（要改什么、验收是什么）</li><li>相关约束（兼容旧接口、不能动公共模块等）</li></ul><p>原则：</p><ul><li>与<strong>本次任务相关</strong>优先，不要一上来贴整仓</li><li>用事实，不写愿景口号</li><li>缺信息就写「未知 / 待确认」，不要让 AI 编</li></ul><hr><h2 id="rules-包含什么" tabindex="-1">Rules 包含什么 <a class="header-anchor" href="#rules-包含什么" aria-label="Permalink to “Rules 包含什么”">​</a></h2><p>让 AI 知道「允许怎么写、禁止怎么写」：</p><ul><li>架构规则（分层、依赖方向）</li><li>编码规则（命名、包结构、日志/异常习惯）</li><li>数据库规则（事务、软删、迁移约定）</li><li>API 规则（错误码、兼容、鉴权）</li><li>测试规则（什么必须有测、怎么验收）</li><li><strong>AI 操作边界</strong>（最重要）</li></ul><p>AI 操作边界示例：</p><ul><li>只改与任务相关的文件</li><li>未经确认不重构</li><li>不擅自改公共 API / 表结构</li><li>不确定先问，再改</li><li>先方案后动手</li></ul><p>Rules 应尽量来自<strong>现有代码真实习惯</strong>，不要一次写一本理想手册。</p><hr><h2 id="单次任务-context-贴进对话-不进仓库" tabindex="-1">单次任务 Context（贴进对话，不进仓库） <a class="header-anchor" href="#单次任务-context-贴进对话-不进仓库" aria-label="Permalink to “单次任务 Context（贴进对话，不进仓库）”">​</a></h2><p>章节标题固定。示例使用落地包中的工单项目，接到别的项目只改名称和路径。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Context（本次任务）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 项目</span></span>
<span class="line"><span>- 名称：ticket-admin</span></span>
<span class="line"><span>- 说明文件：AGENTS.md、docs/ai-context/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 相关模块</span></span>
<span class="line"><span>- 模块：ticket</span></span>
<span class="line"><span>- 调用链：TicketController → TicketService → TicketMapper</span></span>
<span class="line"><span>- 表 / API：biz_ticket；GET /api/tickets</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 当前任务</span></span>
<span class="line"><span>- 目标：列表增加 status 过滤</span></span>
<span class="line"><span>- 验收：status=OPEN 只返回 OPEN；不传参数与改前一致</span></span>
<span class="line"><span>- 明确不做：改 URL、改表、加 Redis</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 约束</span></span>
<span class="line"><span>- 禁止修改：/api/** 路径、其他模块</span></span>
<span class="line"><span>- 已知坑：见 docs/ai-context/99-gotchas.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><hr><h2 id="rules-以落地包为准" tabindex="-1">Rules 以落地包为准 <a class="header-anchor" href="#rules-以落地包为准" aria-label="Permalink to “Rules 以落地包为准”">​</a></h2><p>仓库里只保留 <code>.cursor/rules/00-core.mdc</code>，全文在 <a href="./project-landing-kit.html">项目落地包</a> 第 2 节。<br> 不要在对话里再维护一份「理想规范」。单次任务只在 Prompt 里重复这四条：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>范围：只改本次点名的文件</span></span>
<span class="line"><span>禁止：改 URL、改表、加依赖、改其他模块</span></span>
<span class="line"><span>顺序：先方案，确认后再改</span></span>
<span class="line"><span>验收：写出命令或页面步骤</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="哪些内容应该给-ai" tabindex="-1">哪些内容应该给 AI <a class="header-anchor" href="#哪些内容应该给-ai" aria-label="Permalink to “哪些内容应该给 AI”">​</a></h2><p>优先给：</p><ul><li>当前 Diff</li><li>相关调用链与接口定义</li><li>验收标准与「不要做什么」</li><li>报错原文、复现步骤</li><li>已沉淀的 Context / Rules 摘要</li></ul><p>不要指望 AI 自己「读懂整仓业务政治」。</p><hr><h2 id="修改边界-写进-rules-也写进每次-prompt" tabindex="-1">修改边界（写进 Rules，也写进每次 Prompt） <a class="header-anchor" href="#修改边界-写进-rules-也写进每次-prompt" aria-label="Permalink to “修改边界（写进 Rules，也写进每次 Prompt）”">​</a></h2><p>默认边界：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>可以：在指定范围内实现 / 修复 / 补测试草稿</span></span>
<span class="line"><span>不可以：无关重构、改公共契约、删历史兼容、扩大需求</span></span>
<span class="line"><span>必须：先分析或先方案（按你当轮要求）→ 再改 → 说明副作用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>和 <a href="/my-vitepress-site/ai/dev/coding/cursor-workflow.html">AI Coding 工作流</a>、<a href="/my-vitepress-site/ai/dev/coding/ai-code-review.html">Code Review</a> 同一原则：</p><blockquote><p><strong>人定边界与验收，AI 在边界内提速。</strong></p></blockquote><hr><h2 id="怎么用-个人开发最小用法" tabindex="-1">怎么用（个人开发最小用法） <a class="header-anchor" href="#怎么用-个人开发最小用法" aria-label="Permalink to “怎么用（个人开发最小用法）”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>开任务前：填一版 Context（可很短）</span></span>
<span class="line"><span>  → 有则附上 Rules；没有就先写「AI 操作边界」四条</span></span>
<span class="line"><span>  → 实现 / Review / Debug 时把 Context + 边界贴进 Prompt</span></span>
<span class="line"><span>  → 任务结束后：把踩过的坑补一条进 Rules（有则改，无则先记笔记）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>不必一上来建企业级规范库。先够用，再在实战里长出来。</p>`,49)])])}const u=a(i,[["render",p]]);export{h as __pageData,u as default};
